      await test('CornSyrup simple_effect mandatory runtime arrays, defaults, and external ABI parity',async()=>{
        const CC=window.WC3_EFFECTS_COMPAT_CORPUS,CB=window.WC3_EFFECTS_CFX_BUNDLE_COMPILER,ND=window.WC3_EFFECTS_PKB_NATIVE_POPCORN;
        const built=CB.build(CC.bundle('compat-simple-effect'),{libraries:CC.libraries(),name:'simple_effect_asset_studio.pkb'});
        const rb=ND.Bake.load(CC.referencePkb('compat-simple-effect')),cb=ND.Bake.load(built.bytes);
        const hex=x=>Array.from(x||[]).map(v=>v.toString(16).padStart(2,'0')).join('');
        const count=(bake,record,field)=>{const x=bake.raw(record,field);return x.length>=4?new DataView(x.buffer,x.byteOffset,x.byteLength).getUint32(0,true):-1;};
        const rl=rb.ofClass('CLayerCompileCache'),cl=cb.ofClass('CLayerCompileCache');
        assert(rl.length===3&&cl.length===3,'simple_effect runtime layer count changed',{reference:rl.length,candidate:cl.length});
        const arrays=[];
        for(let i=0;i<3;i++){
          const rc=count(rb,rl[i],0),cc=count(cb,cl[i],0),rr=count(rb,rl[i],1),cr=count(cb,cl[i],1);
          assert(rc===cc&&hex(rb.raw(rl[i],0))===hex(cb.raw(cl[i],0)),`ConstantData diverged for layer ${i}`,{referenceCount:rc,candidateCount:cc});
          assert(rr===cr&&hex(rb.raw(rl[i],1))===hex(cb.raw(cl[i],1)),`RangeData diverged for layer ${i}`,{referenceCount:rr,candidateCount:cr});
          const rf=rb.Refs(rl[i],2),cf=cb.Refs(cl[i],2);
          assert(rf.length===cf.length,`Field count diverged for layer ${i}`);
          for(let j=0;j<rf.length;j++){
            assert(rb.String(rf[j],0)===cb.String(cf[j],0),`Field order/name diverged for layer ${i}/${j}`);
            for(const f of [1,2,3,4,5]){
              const samePresence=rb.has(rf[j],f)===cb.has(cf[j],f);
              const sameValue=!rb.has(rf[j],f)||hex(rb.raw(rf[j],f))===hex(cb.raw(cf[j],f));
              assert(samePresence&&sameValue,`Field ABI metadata diverged for ${rb.String(rf[j],0)} field ${f}`);
            }
          }
          arrays.push({layer:i,constantData:cc,rangeData:cr});
        }
        const re=rb.ofClass('CLayerCompileCacheEvent'),ce=cb.ofClass('CLayerCompileCacheEvent');
        assert(re.length===ce.length,'Runtime event count diverged');
        for(let i=0;i<re.length;i++){
          const a=rb.fieldsOf(re[i]).map(x=>x.field),c=cb.fieldsOf(ce[i]).map(x=>x.field);
          assert(a.join(',')===c.join(','),`Default-field omission diverged for event ${i}`,{reference:a,candidate:c});
        }
        const rs=rb.ofClass('CLayerGraphCompileCache_LayerSlot'),cs=cb.ofClass('CLayerGraphCompileCache_LayerSlot');
        for(let i=0;i<rs.length;i++){
          const a=rb.fieldsOf(rs[i]).map(x=>x.field),c=cb.fieldsOf(cs[i]).map(x=>x.field);
          assert(a.join(',')===c.join(','),`Default empty graph array was serialized for layer slot ${i}`);
        }
        assert(!cb.strings.includes(''),'Standalone build still interns a default empty string');
        const extraStrings=cb.strings.filter(x=>!rb.strings.includes(x)).sort();
        assert(extraStrings.join('|')==='hsv2rgb|rgb2hsv|sample','Unexpected standalone-only strings remain',extraStrings);
        const scripts=(bake,layer)=>{const x=bake.Refs(layer,10).slice(),d=bake.Ref(layer,9);if(d>=0)x.push(d);return x;};
        const extMap=(bake,record)=>{const m=new Map();for(const e of bake.Refs(record,3))m.set(bake.String(e,0),{type:bake.String(e,1),kind:bake.U32(e,2),size:bake.U32(e,3),meta:bake.U32(e,4),attr:bake.has(e,5)?bake.U32(e,5):null,access:bake.U32(e,6)});return m;};
        for(let li=0;li<rl.length;li++){
          const a=scripts(rb,rl[li]),c=scripts(cb,cl[li]);
          assert(a.length===c.length,`Script topology diverged for layer ${li}`);
          for(let si=0;si<a.length;si++){
            const am=extMap(rb,a[si]),cm=extMap(cb,c[si]);
            assert(am.size===cm.size,`External count diverged for layer ${li} script ${si}`);
            for(const [name,row] of am)assert(JSON.stringify(row)===JSON.stringify(cm.get(name)),`External ABI metadata diverged for ${name}`,{layer:li,script:si,reference:row,candidate:cm.get(name)});
          }
        }
        return{arrays,extraStrings,events:re.length,layerSlots:rs.length};
      });
